      declaredScenarioCount: registryScenarioIds.length,
      fixtureCaseCount: totalCaseCount,
      matchedFixtureCaseCount: registryMatchedCaseCount,
    },
    denominators: {
      totalCases: totalCaseCount,
      completeCases: completeCaseCount,
      incompleteCases: incompleteCaseCount,
      passKDenominator: completeCaseCount,
      passKAtLeastOneDenominator: completeCaseCount,
      flakeDenominator: completeCaseCount,
    },
    metrics: {
      passK: { numerator: passKCount, denominator: completeCaseCount, rate: passKRate, definition: 'complete cases whose trials all passed' },
      passKAtLeastOne: { numerator: passKCountAtLeastOne, denominator: completeCaseCount, rate: passKAtLeastOneRate, definition: 'complete cases with at least one passing trial' },
      flake: { numerator: flakeCount, denominator: completeCaseCount, rate: flakeRate, definition: 'complete cases whose first trial failed and every fixed rerun passed' },
      incomplete: { numerator: incompleteCaseCount, denominator: totalCaseCount, rate: incompleteRate },
      missing,
    },
    completeCases,
    incompleteCases,
    anchorViolations,
    safetyViolations,
    gate,
    reasons,
  };
}

