{"edits":[{"path":"scripts/lib/reliability-aggregation.mjs","content":"const TERMINAL_TRIAL_STATUSES = new Set(['passed', 'failed']);
const EXECUTION_FAILURE_STATUSES = new Set(['missing', 'timeout', 'crashed', 'skipped']);

function isFiniteNumber(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

function ratio(numerator, denominator) {
  return denominator === 0 ? null : Number((numerator / denominator).toFixed(6));
}

function requirePositiveInteger(value, name) {
  if (!Number.isInteger(value) || value <= 0) {
    throw new TypeError(`${name} must be a positive integer`);
  }
}

function requireRate(value, name) {
  if (!isFiniteNumber(value) || value < 0 || value > 1) {
    throw new TypeError(`${name} must be a number between 0 and 1`);
  }
}

/**
 * Aggregates the deterministic reliability fixture without treating incomplete
 * executions as successful or failed trials. The caller supplies the registry
 * scenario IDs only for provenance/coverage reporting; this module does not read
 * provider services, credentials, or any external state.
 */
export function aggregateReliability(fixture, registryScenarioIds = []) {
  if (!fixture || typeof fixture !== 'object') {
    throw new TypeError('fixture must be an object');
  }
  const { k, minCases, thresholds = {} } = fixture;
  requirePositiveInteger(k, 'k');
  requirePositiveInteger(minCases, 'minCases');
  const maxFlakeRate = thresholds.maxFlakeRate ?? 0;
  const minPassKRate = thresholds.minPassKRate ?? 1;
  const maxIncompleteRate = thresholds.maxIncompleteRate ?? 0;
  requireRate(maxFlakeRate, 'thresholds.maxFlakeRate');
  requireRate(minPassKRate, 'thresholds.minPassKRate');
  requireRate(maxIncompleteRate, 'thresholds.maxIncompleteRate');
  if (!Array.isArray(fixture.cases)) {
    throw new TypeError('fixture.cases must be an array');
  }

  const registryIds = new Set(registryScenarioIds);
  const completeCases = [];
  const incompleteCases = [];
  const anchorViolations = [];
  const safetyViolations = [];
  const missing = { missing: 0, timeout: 0, crashed: 0, skipped: 0 };
  let passKCount = 0;
  let passKCountAtLeastOne = 0;
  let flakeCount = 0;
  let registryMatchedCaseCount = 0;

  for (const testCase of fixture.cases) {
    if (!testCase || typeof testCase !== 'object') throw new TypeError('each case must be an object');
    if (!Array.isArray(testCase.trials) || testCase.trials.length !== k) {
      throw new TypeError(`case ${testCase.id ?? '<unknown>'} must contain exactly ${k} trials`);
    }
    if (registryIds.has(testCase.scenarioId)) registryMatchedCaseCount += 1;

    const statuses = testCase.trials.map((trial) => trial?.status);
    for (const status of statuses) {
      if (!TERMINAL_TRIAL_STATUSES.has(status) && !EXECUTION_FAILURE_STATUSES.has(status)) {
        throw new TypeError(`case ${testCase.id ?? '<unknown>'} has invalid trial status ${String(status)}`);
      }
      if (EXECUTION_FAILURE_STATUSES.has(status)) missing[status] += 1;
    }

    const incomplete = statuses.some((status) => !TERMINAL_TRIAL_STATUSES.has(status));
    if (incomplete) {
      incompleteCases.push({
        id: testCase.id,
        scenarioId: testCase.scenarioId,
        anchor: testCase.anchor ?? null,
        status: 'incomplete',
        statuses,
      });
      continue;
    }

    const allPassed = statuses.every((status) => status === 'passed');
    const atLeastOnePassed = statuses.some((status) => status === 'passed');
    const firstFailedLaterPassed = statuses[0] === 'failed' && statuses.slice(1).every((status) => status === 'passed');
    if (allPassed) passKCount += 1;
    if (atLeastOnePassed) passKCountAtLeastOne += 1;
    if (firstFailedLaterPassed) flakeCount += 1;

    const anchor = testCase.anchor ?? null;
    let anchorSatisfied = null;
    if (anchor === 'positive') {
      anchorSatisfied = allPassed && testCase.trials.every((trial) => trial.actualOutcome === 'accepted');
    } else if (anchor === 'negative') {
      anchorSatisfied = allPassed && testCase.trials.every((trial) => trial.actualOutcome === 'rejected');
    }
    if (anchorSatisfied === false) {
      anchorViolations.push({ id: testCase.id, scenarioId: testCase.scenarioId, anchor });
    }
    if (testCase.safetyRequired === true && (firstFailedLaterPassed || statuses.includes('skipped'))) {
      safetyViolations.push({
        id: testCase.id,
        scenarioId: testCase.scenarioId,
        reasons: [firstFailedLaterPassed ? 'flake' : null, statuses.includes('skipped') ? 'skip' : null].filter(Boolean),
      });
    }

    completeCases.push({
      id: testCase.id,
      scenarioId: testCase.scenarioId,
      anchor,
      status: allPassed ? 'passed' : 'failed',
      statuses,
      flake: firstFailedLaterPassed,
      anchorSatisfied,
    });
  }

  const completeCaseCount = completeCases.length;
  const totalCaseCount = fixture.cases.length;
  const incompleteCaseCount = incompleteCases.length;
  const incompleteRate = ratio(incompleteCaseCount, totalCaseCount);
  const passKRate = ratio(passKCount, completeCaseCount);
  const passKAtLeastOneRate = ratio(passKCountAtLeastOne, completeCaseCount);
  const flakeRate = ratio(flakeCount, completeCaseCount);
  const reasons = [];

  if (completeCaseCount < minCases) {
    reasons.push(`complete case count ${completeCaseCount} is below the design minimum ${minCases}`);
  }
  if (passKRate === null || passKRate < minPassKRate) {
    reasons.push(`pass^k ${passKRate ?? 'n/a'} is below the pre-registered threshold ${minPassKRate}`);
  }
  if (flakeRate === null || flakeRate > maxFlakeRate) {
    reasons.push(`flake rate ${flakeRate ?? 'n/a'} exceeds the pre-registered threshold ${maxFlakeRate}`);
  }
  if (incompleteRate === null || incompleteRate > maxIncompleteRate) {
    reasons.push(`incomplete rate ${incompleteRate ?? 'n/a'} exceeds the pre-registered threshold ${maxIncompleteRate}`);
  }
  if (anchorViolations.length > 0) {
    reasons.push(`${anchorViolations.length} positive/negative anchor violation(s)`);
  }
  if (safetyViolations.length > 0) {
    reasons.push(`${safetyViolations.length} safety-required item has skip or flake`);
  }

  const gate = completeCaseCount < minCases ? 'insufficient-sample' : reasons.length > 0 ? 'fail' : 'pass';

  return {
    oracle: {
      kind: fixture.oracle?.kind ?? 'deterministic',
      deterministic: fixture.oracle?.deterministic === true,
      providerBacked: false,
      humanBacked: false,
      generalizationClaim: false,
      disclaimer: fixture.oracle?.disclaimer ?? 'Deterministic oracle only; not evidence of real-provider, human, or generalization behavior.',
    },
    design: { k, minCases, thresholds: { minPassKRate, maxFlakeRate, maxIncompleteRate } },
    registry: {
      declaredScenarioCount: registryScenarioIds.length,
      fixtureCaseCount: totalCaseCount,
      matchedFixtureCaseCount: registryMatchedCaseCount,
    },
    denominators: {
      totalCases: totalCaseCount,
      completeCases: completeCaseCount,
      incompleteCases: incompleteCaseCount,
      passKDenominator: completeCaseCount,
      passKAtLeastOneDenominator: completeCaseCount,
      flakeDenominator: completeCaseCount,
    },
    metrics: {
      passK: { numerator: passKCount, denominator: completeCaseCount, rate: passKRate, definition: 'complete cases whose trials all passed' },
      passKAtLeastOne: { numerator: passKCountAtLeastOne, denominator: completeCaseCount, rate: passKAtLeastOneRate, definition: 'complete cases with at least one passing trial' },
      flake: { numerator: flakeCount, denominator: completeCaseCount, rate: flakeRate, definition: 'complete cases whose first trial failed and every fixed rerun passed' },
      incomplete: { numerator: incompleteCaseCount, denominator: totalCaseCount, rate: incompleteRate },
      missing,
    },
    completeCases,
    incompleteCases,
    anchorViolations,
    safetyViolations,
    gate,
    reasons,
  };
}

